import type { Express } from "express";
import { createServer, type Server } from "http";
import cookieParser from "cookie-parser";
import { storage } from "./storage";
import { 
  insertLeadSchema, 
  insertDealSchema, 
  insertActivitySchema, 
  insertZapierWebhookSchema, 
  insertProjectSchema, 
  insertCallbackSchema, 
  insertPricingConfigSchema,
  insertContactSchema,
  insertPipelineStageSchema,
  insertCrmDealSchema,
  insertDealNoteSchema,
  insertTaskSchema,
  insertDealActivitySchema,
  insertLeadQuoteSchema,
  insertLeadHistorySchema,
  DISPOSITIONS,
  STAGES,
} from "@shared/schema";
import { parseLeadFromText, generateFirstMessage, generateCallSummary, generateUnstickSuggestion, generateMorningBrief } from "./ai";
import { triggerWebhook } from "./webhooks";
import pricingRoutes from "./pricingRoutes";
import designRoutes from "./designRoutes";
import { 
  hashPassword, 
  comparePassword, 
  generateAccessToken, 
  generateRefreshToken, 
  verifyRefreshToken, 
  getRefreshTokenExpiry,
  authMiddleware,
  optionalAuthMiddleware,
  requireRole,
  type AuthenticatedRequest
} from "./auth";
import { db } from "./db";
import { crmDeals, pipelineStages, users } from "@shared/schema";
import { eq, and, gte, lte, sql } from "drizzle-orm";

function computeDaysOnStage(stageEnteredAt: Date | null): number {
  if (!stageEnteredAt) return 0;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const stageDate = new Date(stageEnteredAt);
  stageDate.setHours(0, 0, 0, 0);
  const diffMs = today.getTime() - stageDate.getTime();
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

function computeDaysSinceLastDispo(lastDispositionAt: Date | null): number | null {
  if (!lastDispositionAt) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const dispoDate = new Date(lastDispositionAt);
  dispoDate.setHours(0, 0, 0, 0);
  const diffMs = today.getTime() - dispoDate.getTime();
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

function enrichLeadWithComputedFields(lead: any) {
  return {
    ...lead,
    daysOnStage: computeDaysOnStage(lead.stageEnteredAt),
    daysSinceLastDispo: computeDaysSinceLastDispo(lead.lastDispositionAt),
  };
}

async function runLeadAgingAutomation() {
  try {
    const allLeads = await storage.getLeads();
    const nonSoldLeads = allLeads.filter(lead => lead.status !== "sold");

    const stageMappings = [
      { minDays: 30, maxDays: 90, stageName: "reactivation_30" },
      { minDays: 90, maxDays: 180, stageName: "reactivation_90" },
      { minDays: 180, maxDays: 730, stageName: "reactivation_180" },
      { minDays: 730, maxDays: Infinity, stageName: "aged_out" },
    ];

    let updatedCount = 0;
    const updateLog: any[] = [];

    for (const lead of nonSoldLeads) {
      if (!lead.lastDispositionAt) continue;

      const daysSince = computeDaysSinceLastDispo(lead.lastDispositionAt);
      if (daysSince === null) continue;

      const mapping = stageMappings.find(m => daysSince >= m.minDays && daysSince < m.maxDays);
      if (!mapping) continue;

      const oldStage = lead.stage;

      const existingStage = (await storage.getPipelineStages()).find(s => s.name === mapping.stageName);
      if (!existingStage) {
        console.log(`[Lead Aging] Stage "${mapping.stageName}" not found, creating it`);
        await storage.createPipelineStage({
          name: mapping.stageName,
          order: 99,
          isClosed: false,
          isWon: false,
          color: "#6B7280",
        });
      }

      const automationMessage = `Auto-moved by aging rule (${daysSince} days since last disposition)`;

      await storage.updateLead(lead.id, {
        stage: mapping.stageName,
        stageEnteredAt: new Date(),
      });

      await storage.createLeadHistory({
        leadId: lead.id,
        type: "stage_change",
        prevStage: oldStage,
        newStage: mapping.stageName,
        note: automationMessage,
        createdByUserId: null,
      });

      console.log(`[Lead Aging] Lead ${lead.id} (${lead.companyName}): moved from "${oldStage}" to "${mapping.stageName}" (${daysSince} days since dispo)`);

      updateLog.push({
        leadId: lead.id,
        company: lead.companyName,
        oldStage,
        newStage: mapping.stageName,
        daysSince,
      });

      updatedCount++;
    }

    console.log(`[Lead Aging] Automation complete: ${updatedCount} leads updated`);
    return { updatedCount, details: updateLog };
  } catch (error) {
    console.error("[Lead Aging] Error during automation:", error);
    throw error;
  }
}

export async function registerRoutes(app: Express): Promise<Server> {
  app.use(cookieParser());

  app.use("/api/pricing", pricingRoutes);
  app.use("/api/designs", designRoutes);

  app.post("/api/auth/register", async (req, res) => {
    try {
      const { name, email, password, role = "REP" } = req.body;

      if (!name || !email || !password) {
        return res.status(400).json({ error: "Name, email, and password are required" });
      }

      const existingUser = await storage.getUserByEmail(email);
      if (existingUser) {
        return res.status(400).json({ error: "Email already in use" });
      }

      const passwordHash = await hashPassword(password);
      const user = await storage.createUser({
        name,
        email,
        passwordHash,
        role,
        active: true,
      });

      const tokenPayload = { userId: user.id, email: user.email, role: user.role };
      const accessToken = generateAccessToken(tokenPayload);
      const refreshToken = generateRefreshToken(tokenPayload);

      await storage.createRefreshToken({
        userId: user.id,
        token: refreshToken,
        expiresAt: getRefreshTokenExpiry(),
      });

      res.cookie("accessToken", accessToken, {
        httpOnly: true,
        secure: process.env.NODE_ENV === "production",
        sameSite: "lax",
        maxAge: 15 * 60 * 1000,
      });

      res.cookie("refreshToken", refreshToken, {
        httpOnly: true,
        secure: process.env.NODE_ENV === "production",
        sameSite: "lax",
        maxAge: 7 * 24 * 60 * 60 * 1000,
      });

      const { passwordHash: _, ...userWithoutPassword } = user;
      res.json({ user: userWithoutPassword, accessToken });
    } catch (error) {
      console.error("Registration error:", error);
      res.status(500).json({ error: "Registration failed" });
    }
  });

  app.post("/api/auth/login", async (req, res) => {
    try {
      const { email, password } = req.body;

      if (!email || !password) {
        return res.status(400).json({ error: "Email and password are required" });
      }

      const user = await storage.getUserByEmail(email);
      if (!user || !user.passwordHash) {
        return res.status(401).json({ error: "Invalid credentials" });
      }

      const isValid = await comparePassword(password, user.passwordHash);
      if (!isValid) {
        return res.status(401).json({ error: "Invalid credentials" });
      }

      if (!user.active) {
        return res.status(401).json({ error: "Account is inactive" });
      }

      const tokenPayload = { userId: user.id, email: user.email, role: user.role };
      const accessToken = generateAccessToken(tokenPayload);
      const refreshToken = generateRefreshToken(tokenPayload);

      await storage.createRefreshToken({
        userId: user.id,
        token: refreshToken,
        expiresAt: getRefreshTokenExpiry(),
      });

      res.cookie("accessToken", accessToken, {
        httpOnly: true,
        secure: process.env.NODE_ENV === "production",
        sameSite: "lax",
        maxAge: 15 * 60 * 1000,
      });

      res.cookie("refreshToken", refreshToken, {
        httpOnly: true,
        secure: process.env.NODE_ENV === "production",
        sameSite: "lax",
        maxAge: 7 * 24 * 60 * 60 * 1000,
      });

      const { passwordHash: _, ...userWithoutPassword } = user;
      res.json({ user: userWithoutPassword, accessToken });
    } catch (error) {
      console.error("Login error:", error);
      res.status(500).json({ error: "Login failed" });
    }
  });

  app.post("/api/auth/logout", async (req, res) => {
    try {
      const refreshToken = req.cookies?.refreshToken;
      if (refreshToken) {
        await storage.deleteRefreshToken(refreshToken);
      }

      res.clearCookie("accessToken");
      res.clearCookie("refreshToken");
      res.json({ success: true });
    } catch (error) {
      res.status(500).json({ error: "Logout failed" });
    }
  });

  app.post("/api/auth/refresh", async (req, res) => {
    try {
      const refreshToken = req.cookies?.refreshToken;
      if (!refreshToken) {
        return res.status(401).json({ error: "No refresh token" });
      }

      const payload = verifyRefreshToken(refreshToken);
      if (!payload) {
        return res.status(401).json({ error: "Invalid refresh token" });
      }

      const storedToken = await storage.getRefreshToken(refreshToken);
      if (!storedToken || storedToken.expiresAt < new Date()) {
        return res.status(401).json({ error: "Token expired" });
      }

      const user = await storage.getUser(payload.userId);
      if (!user || !user.active) {
        return res.status(401).json({ error: "User not found or inactive" });
      }

      const tokenPayload = { userId: user.id, email: user.email, role: user.role };
      const newAccessToken = generateAccessToken(tokenPayload);

      res.cookie("accessToken", newAccessToken, {
        httpOnly: true,
        secure: process.env.NODE_ENV === "production",
        sameSite: "lax",
        maxAge: 15 * 60 * 1000,
      });

      res.json({ accessToken: newAccessToken });
    } catch (error) {
      res.status(500).json({ error: "Token refresh failed" });
    }
  });

  app.get("/api/auth/me", optionalAuthMiddleware(storage), async (req: AuthenticatedRequest, res) => {
    if (!req.user) {
      return res.status(401).json({ error: "Not authenticated" });
    }
    const { passwordHash: _, ...userWithoutPassword } = req.user;
    res.json(userWithoutPassword);
  });

  app.get("/api/users", async (req, res) => {
    try {
      const allUsers = await storage.getUsers();
      const usersWithoutPasswords = allUsers.map(({ passwordHash, ...user }) => user);
      res.json(usersWithoutPasswords);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch users" });
    }
  });

  app.post("/api/users", async (req, res) => {
    try {
      const { name, email, password, role = "REP" } = req.body;

      if (!name || !email || !password) {
        return res.status(400).json({ error: "Name, email, and password are required" });
      }

      const existingUser = await storage.getUserByEmail(email);
      if (existingUser) {
        return res.status(400).json({ error: "Email already in use" });
      }

      const passwordHash = await hashPassword(password);
      const user = await storage.createUser({
        name,
        email,
        passwordHash,
        role,
        active: true,
      });

      const { passwordHash: _, ...userWithoutPassword } = user;
      res.json(userWithoutPassword);
    } catch (error) {
      res.status(500).json({ error: "Failed to create user" });
    }
  });

  app.patch("/api/users/:id", authMiddleware(storage), async (req: AuthenticatedRequest, res) => {
    try {
      const updates = { ...req.body };
      if (updates.password) {
        updates.passwordHash = await hashPassword(updates.password);
        delete updates.password;
      }

      const user = await storage.updateUser(req.params.id, updates);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      const { passwordHash: _, ...userWithoutPassword } = user;
      res.json(userWithoutPassword);
    } catch (error) {
      res.status(500).json({ error: "Failed to update user" });
    }
  });

  app.delete("/api/users/:id", authMiddleware(storage), requireRole("ADMIN"), async (req: AuthenticatedRequest, res) => {
    try {
      const userId = req.params.id;

      if (userId === req.user!.id) {
        return res.status(400).json({ error: "Cannot delete your own user account" });
      }

      const deleted = await storage.deleteUser(userId);
      if (!deleted) {
        return res.status(404).json({ error: "User not found" });
      }

      return res.status(200).json({ success: true });
    } catch (error) {
      console.error("Error deleting user:", error);
      return res.status(500).json({ error: "Failed to delete user" });
    }
  });

  app.get("/api/contacts", async (req, res) => {
    try {
      const search = req.query.search as string | undefined;
      const allContacts = await storage.getContacts(search);
      res.json(allContacts);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch contacts" });
    }
  });

  app.get("/api/contacts/:id", async (req, res) => {
    try {
      const contact = await storage.getContact(req.params.id);
      if (!contact) {
        return res.status(404).json({ error: "Contact not found" });
      }
      res.json(contact);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch contact" });
    }
  });

  app.post("/api/contacts", async (req, res) => {
    try {
      const validatedData = insertContactSchema.parse(req.body);
      const contact = await storage.createContact(validatedData);
      res.json(contact);
    } catch (error) {
      res.status(400).json({ error: "Invalid contact data" });
    }
  });

  app.patch("/api/contacts/:id", async (req, res) => {
    try {
      const contact = await storage.updateContact(req.params.id, req.body);
      if (!contact) {
        return res.status(404).json({ error: "Contact not found" });
      }
      res.json(contact);
    } catch (error) {
      res.status(500).json({ error: "Failed to update contact" });
    }
  });

  app.delete("/api/contacts/:id", async (req, res) => {
    try {
      const deleted = await storage.deleteContact(req.params.id);
      if (!deleted) {
        return res.status(404).json({ error: "Contact not found" });
      }
      res.status(204).send();
    } catch (error) {
      res.status(500).json({ error: "Failed to delete contact" });
    }
  });

  app.get("/api/admin/pipeline-stages", async (req, res) => {
    try {
      const stages = await storage.getPipelineStages();
      res.json(stages);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch pipeline stages" });
    }
  });

  app.post("/api/admin/pipeline-stages", async (req, res) => {
    try {
      const validatedData = insertPipelineStageSchema.parse(req.body);
      const stage = await storage.createPipelineStage(validatedData);
      res.json(stage);
    } catch (error) {
      res.status(400).json({ error: "Invalid pipeline stage data" });
    }
  });

  app.patch("/api/admin/pipeline-stages/:id", async (req, res) => {
    try {
      const stage = await storage.updatePipelineStage(req.params.id, req.body);
      if (!stage) {
        return res.status(404).json({ error: "Pipeline stage not found" });
      }
      res.json(stage);
    } catch (error) {
      res.status(500).json({ error: "Failed to update pipeline stage" });
    }
  });

  app.delete("/api/admin/pipeline-stages/:id", async (req, res) => {
    try {
      const deleted = await storage.deletePipelineStage(req.params.id);
      if (!deleted) {
        return res.status(404).json({ error: "Pipeline stage not found" });
      }
      res.status(204).send();
    } catch (error) {
      res.status(500).json({ error: "Failed to delete pipeline stage" });
    }
  });

  app.get("/api/crm/deals", async (req, res) => {
    try {
      const { stageId, ownerId, from, to } = req.query;
      const filters: any = {};
      if (stageId) filters.stageId = stageId as string;
      if (ownerId) filters.ownerId = ownerId as string;
      if (from) filters.fromDate = new Date(from as string);
      if (to) filters.toDate = new Date(to as string);

      const allDeals = await storage.getCrmDeals(Object.keys(filters).length > 0 ? filters : undefined);
      res.json(allDeals);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch deals" });
    }
  });

  app.get("/api/crm/deals/:id", async (req, res) => {
    try {
      const deal = await storage.getCrmDeal(req.params.id);
      if (!deal) {
        return res.status(404).json({ error: "Deal not found" });
      }
      res.json(deal);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch deal" });
    }
  });

  app.post("/api/crm/deals", optionalAuthMiddleware(storage), async (req: AuthenticatedRequest, res) => {
    try {
      const validatedData = insertCrmDealSchema.parse(req.body);
      const deal = await storage.createCrmDeal(validatedData);

      await storage.createDealActivity({
        dealId: deal.id,
        userId: req.user?.id,
        type: "DEAL_CREATED",
        data: { title: deal.title, amount: deal.amount },
      });

      res.json(deal);
    } catch (error) {
      res.status(400).json({ error: "Invalid deal data" });
    }
  });

  app.patch("/api/crm/deals/:id", optionalAuthMiddleware(storage), async (req: AuthenticatedRequest, res) => {
    try {
      const existingDeal = await storage.getCrmDeal(req.params.id);
      if (!existingDeal) {
        return res.status(404).json({ error: "Deal not found" });
      }

      const deal = await storage.updateCrmDeal(req.params.id, req.body);

      if (req.body.stageId && req.body.stageId !== existingDeal.stageId) {
        await storage.createDealActivity({
          dealId: deal!.id,
          userId: req.user?.id,
          type: "STAGE_CHANGED",
          data: { oldStageId: existingDeal.stageId, newStageId: req.body.stageId },
        });
      }

      res.json(deal);
    } catch (error) {
      res.status(500).json({ error: "Failed to update deal" });
    }
  });

  app.patch("/api/crm/deals/:id/stage", optionalAuthMiddleware(storage), async (req: AuthenticatedRequest, res) => {
    try {
      const { stageId } = req.body;
      if (!stageId) {
        return res.status(400).json({ error: "stageId is required" });
      }

      const existingDeal = await storage.getCrmDeal(req.params.id);
      if (!existingDeal) {
        return res.status(404).json({ error: "Deal not found" });
      }

      const deal = await storage.updateCrmDeal(req.params.id, { stageId });

      await storage.createDealActivity({
        dealId: deal!.id,
        userId: req.user?.id,
        type: "STAGE_CHANGED",
        data: { oldStageId: existingDeal.stageId, newStageId: stageId },
      });

      res.json(deal);
    } catch (error) {
      res.status(500).json({ error: "Failed to update deal stage" });
    }
  });

  app.delete("/api/crm/deals/:id", async (req, res) => {
    try {
      const deleted = await storage.deleteCrmDeal(req.params.id);
      if (!deleted) {
        return res.status(404).json({ error: "Deal not found" });
      }
      res.status(204).send();
    } catch (error) {
      res.status(500).json({ error: "Failed to delete deal" });
    }
  });

  app.get("/api/crm/deals/:dealId/notes", async (req, res) => {
    try {
      const notes = await storage.getDealNotes(req.params.dealId);
      res.json(notes);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch notes" });
    }
  });

  app.post("/api/crm/deals/:dealId/notes", optionalAuthMiddleware(storage), async (req: AuthenticatedRequest, res) => {
    try {
      const noteData = {
        ...req.body,
        dealId: req.params.dealId,
        authorId: req.body.authorId || req.user?.id,
      };
      const validatedData = insertDealNoteSchema.parse(noteData);
      const note = await storage.createDealNote(validatedData);

      await storage.createDealActivity({
        dealId: req.params.dealId,
        userId: req.user?.id,
        type: "NOTE_ADDED",
        data: { noteId: note.id },
      });

      res.json(note);
    } catch (error) {
      res.status(400).json({ error: "Invalid note data" });
    }
  });

  app.get("/api/tasks", async (req, res) => {
    try {
      const { status, assignedToId, from, to } = req.query;
      const filters: any = {};
      if (status) filters.status = status as string;
      if (assignedToId) filters.assignedToId = assignedToId as string;
      if (from) filters.fromDate = new Date(from as string);
      if (to) filters.toDate = new Date(to as string);

      const allTasks = await storage.getTasks(Object.keys(filters).length > 0 ? filters : undefined);
      res.json(allTasks);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch tasks" });
    }
  });

  app.get("/api/my/tasks", optionalAuthMiddleware(storage), async (req: AuthenticatedRequest, res) => {
    try {
      if (!req.user) {
        return res.status(401).json({ error: "Authentication required" });
      }
