      const x = pos.getX(i); // along beam length (centered)
      const nx = (x + length / 2) / length; // 0 at -L/2, 1 at +L/2

      let edgeWeight = 1 - Math.abs((x) / (length / 2)); // symmetric by default: 1 at edges, 0 at center
