                        if (
                          parent &&
                          parent.wraparound &&
                          (parent.type === 'enclosed' || parent.type === 'open') &&
                          (parent.wall === 'front' || parent.wall === 'back') &&
                          (leanTo.wall === 'left' || leanTo.wall === 'right')
