                  if (leanTo.wraparound) {
                    const hasRightCorner = leanTo.wraparoundCorner === 'right' || leanTo.wraparoundCorner === 'both';
                    const hasLeftCorner = leanTo.wraparoundCorner === 'left' || leanTo.wraparoundCorner === 'both';

