                })()}

                {/* Wraparound corner connecting walls - rectangular L-shapes that meet exactly at the hip corner */}
                {(() => {
                  if (!leanTo.wraparound) return null;

                  const panels = [] as JSX.Element[];
                  const parentWall = leanTo.wall;

