                        <mesh
                          key={`wrap-eave-right-side-${trimColor}`}
                          position={[cornerX, leanToHeight - 0.24, isBackWall ? cornerZ - rightChild.width / 2 - 0.5 : cornerZ + rightChild.width / 2 + 0.5]}
