                  >
                    <boxGeometry args={[window.width, window.height, 0.2]} />
                    <meshStandardMaterial 
                      color="#E0F2FE" 
                      transparent 
                      opacity={0.7}
                      roughness={0.1}
                      metalness={0.5}
