                  </mesh>

                  {/* Window grid */}
                  <group>
                    {/* Horizontal grid line */}
                    <mesh key={`window-grid-h-${window.id}-${trimColor}`} position={[0, 0, 0]}>
                      <boxGeometry args={[window.width, 0.08, 0.21]} />
                      <meshStandardMaterial color={resolveColor(trimColor)} metalness={0.8} roughness={0.35} />
