                    {/* Right side wall (local +Z) - matches door placement convention */}
                    <mesh 
                      key={`leanto-gable-sidewall-right-${leanTo.id}-${wallColor}`} 
                      position={[0, leanToHeight / 2, effectiveLength / 2]} 
                      rotation={[0, Math.PI, 0]}
                      onClick={(e) => {
