                    >
                      <boxGeometry args={[effectiveWidth - 0.4, leanToHeight, 0.2]} />
                      <meshStandardMaterial 
                        color={resolveColor(wallColor)}
                        metalness={0.9}
                        roughness={0.2}
                        bumpMap={wallBump}
                        bumpScale={0.3}
