                      <mesh key={`leanto-gable-rake-right-${trimColor}`} position={tfOuterR.position} quaternion={tfOuterR.quaternion}>
                        <boxGeometry args={[0.3, tfOuterR.length + 0.3, 0.3]} />
                        <primitive attach="material" object={trimMaterial} />
                      </mesh>

