                          <mesh key={`leanto-gable-corner-1-${trimColor}`} position={[effectiveWidth / 2, leanToHeight / 2, -attachWallLength / 2]}>
                            <boxGeometry args={[0.3, leanToHeight, 0.3]} />
                            <primitive attach="material" object={trimMaterial} />
