            ) : (
              // Enclosed or Open lean-to - single slope roof
              <>
                {/* Side walls (for enclosed type only) */}
                {leanTo.type === 'enclosed' && (
                  <mesh 
                    position={[effectiveWidth / 2, leanToHeight / 2, 0]}
                    onClick={(e) => {
