import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Skeleton } from "@/components/ui/skeleton";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Plus, LayoutGrid, Table as TableIcon, DollarSign, User, Building } from "lucide-react";
import type { CrmDeal, PipelineStage, Contact, User as UserType } from "@shared/schema";

export default function CrmDealsPage() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [viewMode, setViewMode] = useState<"kanban" | "table">("kanban");
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [newDeal, setNewDeal] = useState({ title: "", amount: "", contactId: "", stageId: "" });

  const { data: deals = [], isLoading: dealsLoading } = useQuery<CrmDeal[]>({
    queryKey: ["/api/crm/deals"],
  });

  const { data: stages = [], isLoading: stagesLoading } = useQuery<PipelineStage[]>({
    queryKey: ["/api/admin/pipeline-stages"],
  });

  const { data: contacts = [] } = useQuery<Contact[]>({
    queryKey: ["/api/contacts"],
  });

  const { data: users = [] } = useQuery<UserType[]>({
    queryKey: ["/api/users"],
  });

  const createDealMutation = useMutation({
    mutationFn: async (dealData: { title: string; amount: string; contactId?: string; stageId?: string }) => {
      const response = await apiRequest("POST", "/api/crm/deals", {
        ...dealData,
        amount: dealData.amount || "0",
      });
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/crm/deals"] });
      setIsCreateDialogOpen(false);
      setNewDeal({ title: "", amount: "", contactId: "", stageId: "" });
      toast({ title: "Deal created successfully" });
    },
    onError: (error: any) => {
      toast({ variant: "destructive", title: "Failed to create deal", description: error.message });
    },
  });

  const updateDealStageMutation = useMutation({
    mutationFn: async ({ dealId, stageId }: { dealId: string; stageId: string }) => {
      const response = await apiRequest("PATCH", `/api/crm/deals/${dealId}/stage`, { stageId });
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/crm/deals"] });
    },
  });

  const handleDragStart = (e: React.DragEvent, dealId: string) => {
    e.dataTransfer.setData("dealId", dealId);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent, stageId: string) => {
    e.preventDefault();
    const dealId = e.dataTransfer.getData("dealId");
    if (dealId) {
      updateDealStageMutation.mutate({ dealId, stageId });
    }
  };

  const getStageColor = (stage: PipelineStage) => {
    if (stage.isWon) return "bg-green-500/20 text-green-500 border-green-500/30";
    if (stage.isClosed) return "bg-red-500/20 text-red-500 border-red-500/30";
    return "bg-blue-500/20 text-blue-500 border-blue-500/30";
  };

  const formatCurrency = (amount: string | null | undefined) => {
    const num = parseFloat(amount || "0");
    return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(num);
  };

  const getContactName = (contactId: string | null) => {
    if (!contactId) return "No contact";
    const contact = contacts.find(c => c.id === contactId);
    return contact?.name || "Unknown";
  };

  const getUserName = (userId: string | null) => {
    if (!userId) return "Unassigned";
    const user = users.find(u => u.id === userId);
    return user?.name || "Unknown";
  };

  if (dealsLoading || stagesLoading) {
    return (
      <div className="p-6 space-y-4">
        <Skeleton className="h-10 w-48" />
        <div className="flex gap-4">
          {[1, 2, 3, 4].map(i => (
            <Skeleton key={i} className="h-96 w-64" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 sm:p-6 h-full flex flex-col overflow-hidden">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6 flex-shrink-0">
        <div>
          <h1 className="text-2xl font-bold">Deals Pipeline</h1>
          <p className="text-muted-foreground">Manage your sales deals</p>
        </div>
        <div className="flex items-center gap-2">
          <Tabs value={viewMode} onValueChange={(v) => setViewMode(v as "kanban" | "table")}>
            <TabsList>
              <TabsTrigger value="kanban" data-testid="button-view-kanban">
                <LayoutGrid className="h-4 w-4" />
              </TabsTrigger>
              <TabsTrigger value="table" data-testid="button-view-table">
                <TableIcon className="h-4 w-4" />
              </TabsTrigger>
            </TabsList>
          </Tabs>
          <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
            <DialogTrigger asChild>
              <Button data-testid="button-create-deal">
                <Plus className="h-4 w-4 mr-2" />
                New Deal
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Create New Deal</DialogTitle>
              </DialogHeader>
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label>Title</Label>
                  <Input
                    value={newDeal.title}
                    onChange={(e) => setNewDeal({ ...newDeal, title: e.target.value })}
                    placeholder="Deal title"
                    data-testid="input-deal-title"
                  />
                </div>
                <div className="space-y-2">
                  <Label>Amount</Label>
                  <Input
                    type="number"
                    value={newDeal.amount}
                    onChange={(e) => setNewDeal({ ...newDeal, amount: e.target.value })}
                    placeholder="0.00"
                    data-testid="input-deal-amount"
                  />
                </div>
                <div className="space-y-2">
                  <Label>Contact</Label>
                  <Select value={newDeal.contactId} onValueChange={(v) => setNewDeal({ ...newDeal, contactId: v })}>
                    <SelectTrigger data-testid="select-deal-contact">
                      <SelectValue placeholder="Select contact" />
                    </SelectTrigger>
                    <SelectContent>
                      {contacts.map((contact) => (
                        <SelectItem key={contact.id} value={contact.id}>
                          {contact.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Stage</Label>
                  <Select value={newDeal.stageId} onValueChange={(v) => setNewDeal({ ...newDeal, stageId: v })}>
                    <SelectTrigger data-testid="select-deal-stage">
                      <SelectValue placeholder="Select stage" />
                    </SelectTrigger>
                    <SelectContent>
                      {stages.map((stage) => (
                        <SelectItem key={stage.id} value={stage.id}>
                          {stage.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <Button
                  className="w-full"
                  onClick={() => createDealMutation.mutate(newDeal)}
                  disabled={!newDeal.title || createDealMutation.isPending}
                  data-testid="button-submit-deal"
                >
                  {createDealMutation.isPending ? "Creating..." : "Create Deal"}
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </div>
      </div>

      {viewMode === "kanban" ? (
        <div className="flex-1 overflow-x-auto min-h-0">
          <div className="flex gap-4 h-full pb-4" style={{ minWidth: `${stages.length * 280}px` }}>
            {stages.map((stage) => {
              const stageDeals = deals.filter((d) => d.stageId === stage.id);
              const stageTotal = stageDeals.reduce((sum, d) => sum + parseFloat(d.amount || "0"), 0);

              return (
                <div
                  key={stage.id}
                  className="w-72 flex-shrink-0 flex flex-col bg-muted/30 rounded-lg"
                  onDragOver={handleDragOver}
                  onDrop={(e) => handleDrop(e, stage.id)}
                  data-testid={`stage-column-${stage.id}`}
                >
                  <div className="p-3 border-b border-border">
                    <div className="flex items-center justify-between">
                      <h3 className="font-medium">{stage.name}</h3>
                      <Badge variant="secondary" className="text-xs">
                        {stageDeals.length}
                      </Badge>
                    </div>
                    <p className="text-sm text-muted-foreground mt-1">
                      {formatCurrency(stageTotal.toString())}
                    </p>
                  </div>
                  <div className="flex-1 p-2 space-y-2 overflow-y-auto">
                    {stageDeals.map((deal) => (
                      <Card
                        key={deal.id}
                        className="cursor-pointer hover-elevate"
                        draggable
                        onDragStart={(e) => handleDragStart(e, deal.id)}
                        onClick={() => setLocation(`/crm/deals/${deal.id}`)}
                        data-testid={`deal-card-${deal.id}`}
                      >
                        <CardContent className="p-3 space-y-2">
                          <h4 className="font-medium text-sm truncate">{deal.title}</h4>
                          <div className="flex items-center gap-2 text-xs text-muted-foreground">
                            <DollarSign className="h-3 w-3" />
                            {formatCurrency(deal.amount)}
                          </div>
                          <div className="flex items-center gap-2 text-xs text-muted-foreground">
                            <Building className="h-3 w-3" />
                            {getContactName(deal.contactId)}
                          </div>
                          <div className="flex items-center gap-2 text-xs text-muted-foreground">
                            <User className="h-3 w-3" />
                            {getUserName(deal.ownerId)}
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ) : (
        <div className="flex-1 overflow-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Title</TableHead>
                <TableHead>Amount</TableHead>
                <TableHead>Stage</TableHead>
                <TableHead>Contact</TableHead>
                <TableHead>Owner</TableHead>
                <TableHead>Created</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {deals.map((deal) => {
                const stage = stages.find((s) => s.id === deal.stageId);
                return (
                  <TableRow
                    key={deal.id}
                    className="cursor-pointer"
                    onClick={() => setLocation(`/crm/deals/${deal.id}`)}
                    data-testid={`deal-row-${deal.id}`}
                  >
                    <TableCell className="font-medium">{deal.title}</TableCell>
                    <TableCell>{formatCurrency(deal.amount)}</TableCell>
                    <TableCell>
                      {stage && (
                        <Badge className={getStageColor(stage)}>{stage.name}</Badge>
                      )}
                    </TableCell>
                    <TableCell>{getContactName(deal.contactId)}</TableCell>
                    <TableCell>{getUserName(deal.ownerId)}</TableCell>
                    <TableCell className="text-muted-foreground">
                      {new Date(deal.createdAt).toLocaleDateString()}
                    </TableCell>
                  </TableRow>
                );
              })}
              {deals.length === 0 && (
                <TableRow>
                  <TableCell colSpan={6} className="text-center text-muted-foreground py-8">
                    No deals yet. Create your first deal to get started.
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </div>
      )}
    </div>
  );
}

client/src/pages/crm-reports.tsx.content:
import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Skeleton } from "@/components/ui/skeleton";
import { DollarSign, TrendingUp, Users, Target, BarChart3 } from "lucide-react";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, LineChart, Line } from "recharts";

interface Summary {
  totalPipelineValue: number;
  totalWonValue: number;
  newLeadsCount: number;
  winRate: number;
}

interface RevenueData {
  periodStart: string;
  periodEnd: string;
  totalWon: number;
}

interface DealsByStage {
  stageId: string;
  stageName: string;
  count: number;
  totalValue: number;
}

interface PerformanceByRep {
  userId: string;
  name: string;
  dealsCount: number;
  wonDealsCount: number;
  totalWon: number;
}

const COLORS = ["#0088FE", "#00C49F", "#FFBB28", "#FF8042", "#8884D8", "#82CA9D"];

export default function CrmReportsPage() {
  const [dateRange, setDateRange] = useState({
    from: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split("T")[0],
    to: new Date().toISOString().split("T")[0],
  });
  const [interval, setInterval] = useState("month");

  const { data: summary, isLoading: summaryLoading } = useQuery<Summary>({
    queryKey: ["/api/reports/summary", dateRange.from, dateRange.to],
    queryFn: async () => {
      const res = await fetch(`/api/reports/summary?from=${dateRange.from}&to=${dateRange.to}`);
      return res.json();
    },
  });

  const { data: revenueData = [], isLoading: revenueLoading } = useQuery<RevenueData[]>({
    queryKey: ["/api/reports/revenue-over-time", interval],
    queryFn: async () => {
      const res = await fetch(`/api/reports/revenue-over-time?interval=${interval}`);
      return res.json();
    },
  });

  const { data: dealsByStage = [], isLoading: stagesLoading } = useQuery<DealsByStage[]>({
    queryKey: ["/api/reports/deals-by-stage"],
    queryFn: async () => {
      const res = await fetch("/api/reports/deals-by-stage");
      return res.json();
    },
  });

  const { data: performanceData = [], isLoading: performanceLoading } = useQuery<PerformanceByRep[]>({
    queryKey: ["/api/reports/performance-by-rep"],
    queryFn: async () => {
      const res = await fetch("/api/reports/performance-by-rep");
      return res.json();
    },
  });

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(amount);
  };

  const formatShortCurrency = (amount: number) => {
    if (amount >= 1000000) return `$${(amount / 1000000).toFixed(1)}M`;
    if (amount >= 1000) return `$${(amount / 1000).toFixed(1)}K`;
    return `$${amount.toFixed(0)}`;
  };

  if (summaryLoading) {
    return (
      <div className="p-6 space-y-4">
        <Skeleton className="h-10 w-48" />
        <div className="grid grid-cols-4 gap-4">
          {[1, 2, 3, 4].map(i => <Skeleton key={i} className="h-32" />)}
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 sm:p-6 h-full overflow-auto">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-bold">Reports & Analytics</h1>
          <p className="text-muted-foreground">Track your sales performance</p>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <Label>From</Label>
            <Input
              type="date"
              value={dateRange.from}
              onChange={(e) => setDateRange({ ...dateRange, from: e.target.value })}
              className="w-40"
              data-testid="input-date-from"
            />
          </div>
          <div className="flex items-center gap-2">
            <Label>To</Label>
            <Input
              type="date"
              value={dateRange.to}
              onChange={(e) => setDateRange({ ...dateRange, to: e.target.value })}
              className="w-40"
              data-testid="input-date-to"
            />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        <Card data-testid="card-pipeline-value">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">Pipeline Value</p>
                <p className="text-2xl font-bold">{formatCurrency(summary?.totalPipelineValue || 0)}</p>
              </div>
              <div className="h-10 w-10 rounded-lg bg-blue-500/10 flex items-center justify-center">
                <DollarSign className="h-5 w-5 text-blue-500" />
              </div>
            </div>
          </CardContent>
        </Card>

        <Card data-testid="card-won-value">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">Won Value</p>
                <p className="text-2xl font-bold">{formatCurrency(summary?.totalWonValue || 0)}</p>
              </div>
              <div className="h-10 w-10 rounded-lg bg-green-500/10 flex items-center justify-center">
                <TrendingUp className="h-5 w-5 text-green-500" />
              </div>
            </div>
          </CardContent>
        </Card>

        <Card data-testid="card-new-leads">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">New Leads</p>
                <p className="text-2xl font-bold">{summary?.newLeadsCount || 0}</p>
              </div>
              <div className="h-10 w-10 rounded-lg bg-purple-500/10 flex items-center justify-center">
                <Users className="h-5 w-5 text-purple-500" />
              </div>
            </div>
          </CardContent>
        </Card>

        <Card data-testid="card-win-rate">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-muted-foreground">Win Rate</p>
                <p className="text-2xl font-bold">{summary?.winRate || 0}%</p>
              </div>
              <div className="h-10 w-10 rounded-lg bg-orange-500/10 flex items-center justify-center">
                <Target className="h-5 w-5 text-orange-500" />
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle>Revenue Over Time</CardTitle>
            <Select value={interval} onValueChange={setInterval}>
              <SelectTrigger className="w-32" data-testid="select-interval">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="week">Weekly</SelectItem>
                <SelectItem value="month">Monthly</SelectItem>
              </SelectContent>
            </Select>
          </CardHeader>
          <CardContent>
            {revenueLoading ? (
              <Skeleton className="h-64" />
            ) : revenueData.length > 0 ? (
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={revenueData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                  <XAxis
                    dataKey="periodStart"
                    stroke="hsl(var(--muted-foreground))"
                    tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 12 }}
                  />
                  <YAxis
                    stroke="hsl(var(--muted-foreground))"
                    tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 12 }}
                    tickFormatter={(value) => formatShortCurrency(value)}
                  />
                  <Tooltip
                    formatter={(value: number) => formatCurrency(value)}
                    contentStyle={{
                      backgroundColor: "hsl(var(--card))",
                      border: "1px solid hsl(var(--border))",
                      borderRadius: "8px",
                    }}
                  />
                  <Line
                    type="monotone"
                    dataKey="totalWon"
                    stroke="hsl(var(--primary))"
                    strokeWidth={2}
                    dot={{ fill: "hsl(var(--primary))" }}
                  />
                </LineChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-64 flex items-center justify-center text-muted-foreground">
                No revenue data available
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Deals by Stage</CardTitle>
          </CardHeader>
          <CardContent>
            {stagesLoading ? (
              <Skeleton className="h-64" />
            ) : dealsByStage.length > 0 ? (
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={dealsByStage} layout="vertical">
                  <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                  <XAxis
                    type="number"
                    stroke="hsl(var(--muted-foreground))"
                    tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 12 }}
                  />
                  <YAxis
                    type="category"
                    dataKey="stageName"
                    stroke="hsl(var(--muted-foreground))"
                    tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 12 }}
                    width={100}
                  />
                  <Tooltip
                    contentStyle={{
                      backgroundColor: "hsl(var(--card))",
                      border: "1px solid hsl(var(--border))",
                      borderRadius: "8px",
                    }}
                  />
                  <Bar dataKey="count" fill="hsl(var(--primary))" radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-64 flex items-center justify-center text-muted-foreground">
                No deals data available
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Performance by Rep</CardTitle>
        </CardHeader>
        <CardContent>
          {performanceLoading ? (
            <Skeleton className="h-64" />
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Sales Rep</TableHead>
                  <TableHead className="text-right">Total Deals</TableHead>
                  <TableHead className="text-right">Won Deals</TableHead>
                  <TableHead className="text-right">Win Rate</TableHead>
                  <TableHead className="text-right">Total Won</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {performanceData.map((rep) => (
                  <TableRow key={rep.userId} data-testid={`rep-row-${rep.userId}`}>
                    <TableCell className="font-medium">{rep.name}</TableCell>
                    <TableCell className="text-right">{rep.dealsCount}</TableCell>
                    <TableCell className="text-right">{rep.wonDealsCount}</TableCell>
                    <TableCell className="text-right">
                      {rep.dealsCount > 0 ? Math.round((rep.wonDealsCount / rep.dealsCount) * 100) : 0}%
                    </TableCell>
                    <TableCell className="text-right font-medium">{formatCurrency(rep.totalWon)}</TableCell>
                  </TableRow>
                ))}
                {performanceData.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={5} className="text-center text-muted-foreground py-8">
                      No performance data available
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/login.tsx.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/lib/auth";
import { Building2 } from "lucide-react";

export default function LoginPage() {
  const [, setLocation] = useLocation();
  const { login } = useAuth();
  const { toast } = useToast();
  const [isLoading, setIsLoading] = useState(false);

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      await login(email, password);
      toast({ title: "Welcome back!" });
      setLocation("/crm/deals");
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Login failed",
        description: error.message,
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-background p-4">
      <Card className="w-full max-w-md">
        <CardHeader className="text-center">
          <div className="flex justify-center mb-4">
            <div className="h-12 w-12 rounded-lg bg-primary flex items-center justify-center">
              <Building2 className="h-6 w-6 text-primary-foreground" />
            </div>
          </div>
          <CardTitle>Prefabricated Iron CRM</CardTitle>
          <CardDescription>Sign in to manage your deals and contacts</CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleLogin} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                placeholder="you@company.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                data-testid="input-login-email"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="password">Password</Label>
              <Input
                id="password"
                type="password"
                placeholder="Enter your password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                data-testid="input-login-password"
              />
            </div>
            <Button type="submit" className="w-full" disabled={isLoading} data-testid="button-login">
              {isLoading ? "Signing in..." : "Sign In"}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/crm-admin.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Plus, Trash2, Pencil, GripVertical, Users, Layers, Settings, Save, Loader2, Zap } from "lucide-react";
import type { User, PipelineStage } from "@shared/schema";

export default function CrmAdminPage() {
  const { toast } = useToast();

  const [isUserDialogOpen, setIsUserDialogOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userForm, setUserForm] = useState({ name: "", email: "", password: "", role: "REP" });
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteText, setDeleteText] = useState("");

  const [isStageDialogOpen, setIsStageDialogOpen] = useState(false);
  const [editingStage, setEditingStage] = useState<PipelineStage | null>(null);
  const [stageForm, setStageForm] = useState({ name: "", order: 0, isClosed: false, isWon: false, color: "#6B7280" });

  const [settingsForm, setSettingsForm] = useState<Record<string, any>>({});

  const { data: users = [], isLoading: usersLoading } = useQuery<User[]>({
    queryKey: ["/api/users"],
    queryFn: async () => {
      const res = await apiRequest("GET", "/api/users");
      return res.json();
    },
  });

  const { data: stages = [], isLoading: stagesLoading } = useQuery<PipelineStage[]>({
    queryKey: ["/api/admin/pipeline-stages"],
  });

  const { data: settings = {}, isLoading: settingsLoading } = useQuery<Record<string, any>>({
    queryKey: ["/api/admin/settings"],
    queryFn: async () => {
      const res = await fetch("/api/admin/settings");
      const data = await res.json();
      setSettingsForm(data);
      return data;
    },
  });

  const createUserMutation = useMutation({
    mutationFn: async (data: typeof userForm) => {
      const response = await apiRequest("POST", "/api/users", data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/users"] });
      setIsUserDialogOpen(false);
      setUserForm({ name: "", email: "", password: "", role: "REP" });
      toast({ title: "User created successfully" });
    },
    onError: (error: any) => {
      toast({ variant: "destructive", title: "Failed to create user", description: error.message });
    },
  });

  const updateUserMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: Partial<User> }) => {
      const response = await apiRequest("PATCH", `/api/users/${id}`, data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/users"] });
      setEditingUser(null);
      setUserForm({ name: "", email: "", password: "", role: "REP" });
      toast({ title: "User updated successfully" });
    },
    onError: (error: any) => {
      toast({ variant: "destructive", title: "Failed to update user", description: error.message });
    },
  });

  const deleteUserMutation = useMutation({
    mutationFn: async (id: string) => {
      console.log("[deleteUserMutation] mutationFn start", { id });
      // apiRequest throws automatically on non-2xx
      await apiRequest("DELETE", `/api/users/${id}`);
      console.log("[deleteUserMutation] mutationFn success", { id });
    },
    onSuccess: () => {
      console.log("[deleteUserMutation] onSuccess fired");
      // Refresh the users list
      queryClient.invalidateQueries({ queryKey: ["/api/users"] });
      // Close dialogs and clear state
      setShowDeleteConfirm(false);
      setDeleteText("");
      setEditingUser(null);
      setIsUserDialogOpen(false);
      toast({
        title: "User deleted successfully",
      });
    },
    onError: (error: any) => {
      console.error("[deleteUserMutation] onError", error);
      const message = String(error?.message ?? "Unknown error");

      if (message.includes("Cannot delete your own user account")) {
        toast({
          variant: "destructive",
          title: "You can't delete your own account",
          description: "Log in as a different admin to delete this user.",
        });
      } else {
        toast({
          variant: "destructive",
          title: "Failed to delete user",
          description: message,
        });
      }
    },
  });

  const createStageMutation = useMutation({
    mutationFn: async (data: typeof stageForm) => {
      const response = await apiRequest("POST", "/api/admin/pipeline-stages", data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/pipeline-stages"] });
      setIsStageDialogOpen(false);
      setStageForm({ name: "", order: 0, isClosed: false, isWon: false, color: "#6B7280" });
      toast({ title: "Stage created successfully" });
    },
    onError: (error: any) => {
      toast({ variant: "destructive", title: "Failed to create stage", description: error.message });
    },
  });

  const updateStageMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: Partial<PipelineStage> }) => {
      const response = await apiRequest("PATCH", `/api/admin/pipeline-stages/${id}`, data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/pipeline-stages"] });
      setEditingStage(null);
      setStageForm({ name: "", order: 0, isClosed: false, isWon: false, color: "#6B7280" });
      toast({ title: "Stage updated successfully" });
    },
    onError: (error: any) => {
      toast({ variant: "destructive", title: "Failed to update stage", description: error.message });
    },
  });

  const deleteStageMutation = useMutation({
    mutationFn: async (id: string) => {
      await apiRequest("DELETE", `/api/admin/pipeline-stages/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/pipeline-stages"] });
      toast({ title: "Stage deleted" });
    },
    onError: (error: any) => {
      toast({ variant: "destructive", title: "Failed to delete stage", description: error.message });
    },
  });

  const saveSettingsMutation = useMutation({
    mutationFn: async (data: Record<string, any>) => {
      const response = await apiRequest("PUT", "/api/admin/settings", data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/settings"] });
      toast({ title: "Settings saved successfully" });
    },
    onError: (error: any) => {
      toast({ variant: "destructive", title: "Failed to save settings", description: error.message });
    },
  });

  const runAgingAutomationMutation = useMutation({
    mutationFn: async () => {
      const response = await apiRequest("POST", "/api/admin/run-lead-aging", {});
      return response.json();
    },
    onSuccess: (data: any) => {
      queryClient.invalidateQueries({ queryKey: ["/api/leads"] });
      toast({ 
        title: "Lead aging automation complete", 
        description: `Updated ${data.updatedCount} leads`
      });
    },
    onError: (error: any) => {
      toast({ 
        variant: "destructive", 
        title: "Failed to run automation", 
        description: error.message 
      });
    },
  });

  const handleUserSubmit = () => {
    if (editingUser) {
      const updates: any = { name: userForm.name, email: userForm.email, role: userForm.role };
      if (userForm.password) updates.password = userForm.password;
      updateUserMutation.mutate({ id: editingUser.id, data: updates });
    } else {
      createUserMutation.mutate(userForm);
    }
  };

  const handleConfirmDelete = () => {
    console.log("[handleConfirmDelete] called", { editingUser, deleteText });
    if (!editingUser || deleteText.trim() !== "Delete") return;
    deleteUserMutation.mutate(editingUser.id);
  };

  const handleStageSubmit = () => {
    if (editingStage) {
      updateStageMutation.mutate({ id: editingStage.id, data: stageForm });
    } else {
      createStageMutation.mutate(stageForm);
    }
  };

  const openEditUserDialog = (user: User) => {
    setEditingUser(user);
    setUserForm({ name: user.name, email: user.email, password: "", role: user.role });
  };

  const openEditStageDialog = (stage: PipelineStage) => {
    setEditingStage(stage);
    setStageForm({
      name: stage.name,
      order: stage.order,
      isClosed: stage.isClosed,
      isWon: stage.isWon,
      color: stage.color || "#6B7280",
    });
  };

  const getRoleBadgeVariant = (role: string) => {
    switch (role) {
      case "ADMIN": return "destructive";
      case "MANAGER": return "default";
      default: return "secondary";
    }
  };

  return (
    <div className="p-4 sm:p-6 h-full overflow-auto">
      <div className="mb-6">
        <h1 className="text-2xl font-bold">Admin Settings</h1>
        <p className="text-muted-foreground">Manage users, pipeline stages, and settings</p>
      </div>

      <Tabs defaultValue="users">
        <TabsList className="mb-4">
          <TabsTrigger value="users" data-testid="tab-users">
            <Users className="h-4 w-4 mr-2" />
            Users
          </TabsTrigger>
          <TabsTrigger value="pipeline" data-testid="tab-pipeline">
            <Layers className="h-4 w-4 mr-2" />
            Pipeline Stages
          </TabsTrigger>
          <TabsTrigger value="settings" data-testid="tab-settings">
            <Settings className="h-4 w-4 mr-2" />
            Settings
          </TabsTrigger>
        </TabsList>

        <TabsContent value="users">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle>User Management</CardTitle>
                <CardDescription>Manage user accounts and roles</CardDescription>
              </div>
              <Dialog open={isUserDialogOpen || !!editingUser} onOpenChange={(open) => {
                if (!open) {
                  setIsUserDialogOpen(false);
                  setEditingUser(null);
                  setUserForm({ name: "", email: "", password: "", role: "REP" });
                  setShowDeleteConfirm(false);
                  setDeleteText("");
                }
              }}>
                <DialogTrigger asChild>
                  <Button onClick={() => setIsUserDialogOpen(true)} data-testid="button-create-user">
                    <Plus className="h-4 w-4 mr-2" />
                    Add User
                  </Button>
                </DialogTrigger>
                <DialogContent>
                  <DialogHeader>
                    <DialogTitle>{editingUser ? "Edit User" : "Create New User"}</DialogTitle>
                  </DialogHeader>
                  {!showDeleteConfirm ? (
                    <div className="space-y-4">
                      <div className="space-y-2">
                        <Label>Name</Label>
                        <Input
                          value={userForm.name}
                          onChange={(e) => setUserForm({ ...userForm, name: e.target.value })}
                          placeholder="Full name"
                          data-testid="input-user-name"
                        />
                      </div>
                      <div className="space-y-2">
                        <Label>Email</Label>
                        <Input
                          type="email"
                          value={userForm.email}
                          onChange={(e) => setUserForm({ ...userForm, email: e.target.value })}
                          placeholder="email@company.com"
                          data-testid="input-user-email"
                        />
                      </div>
                      <div className="space-y-2">
                        <Label>{editingUser ? "New Password (leave blank to keep current)" : "Password"}</Label>
                        <Input
                          type="password"
                          value={userForm.password}
                          onChange={(e) => setUserForm({ ...userForm, password: e.target.value })}
                          placeholder={editingUser ? "Enter new password" : "Create password"}
                          data-testid="input-user-password"
                        />
                      </div>
                      <div className="space-y-2">
                        <Label>Role</Label>
                        <Select value={userForm.role} onValueChange={(v) => setUserForm({ ...userForm, role: v })}>
                          <SelectTrigger data-testid="select-user-role">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="REP">Sales Rep</SelectItem>
                            <SelectItem value="MANAGER">Manager</SelectItem>
                            <SelectItem value="ADMIN">Admin</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                      <div className="flex flex-col gap-3">
                        <Button
                          className="w-full"
                          onClick={handleUserSubmit}
                          disabled={!userForm.name || !userForm.email || (!editingUser && !userForm.password) || createUserMutation.isPending || updateUserMutation.isPending}
                          data-testid="button-submit-user"
                        >
                          {createUserMutation.isPending || updateUserMutation.isPending
                            ? "Saving..."
                            : editingUser
                            ? "Update User"
                            : "Create User"}
                        </Button>
                        {editingUser && (
                          <Button
                            type="button"
                            variant="destructive"
                            onClick={() => setShowDeleteConfirm(true)}
                            disabled={createUserMutation.isPending || updateUserMutation.isPending}
                            data-testid="button-delete-user"
                          >
                            Delete User
                          </Button>
                        )}
                      </div>
                    </div>
                  ) : (
                    <div className="space-y-4">
                      <div className="text-sm text-muted-foreground">
                        Are you sure you want to delete this user? Type "Delete" to confirm.
                      </div>
                      <Input
                        type="text"
                        value={deleteText}
                        onChange={(e) => setDeleteText(e.target.value)}
                        placeholder='Type "Delete" to confirm'
                        data-testid="input-delete-confirm"
                      />
                      <div className="flex gap-3 justify-end">
                        <Button
                          type="button"
                          variant="outline"
                          onClick={() => {
                            setShowDeleteConfirm(false);
                            setDeleteText("");
                          }}
                          disabled={deleteUserMutation.isPending}
                          data-testid="button-cancel-delete"
                        >
                          Cancel
                        </Button>
                        <Button
                          type="button"
                          variant="destructive"
                          onClick={handleConfirmDelete}
                          disabled={deleteText.trim() !== "Delete" || deleteUserMutation.isPending}
                          data-testid="button-confirm-delete"
                        >
                          {deleteUserMutation.isPending ? (
                            <>
                              <Loader2 className="h-4 w-4 animate-spin mr-2" />
                              Deleting...
                            </>
                          ) : (
                            "Delete"
                          )}
                        </Button>
                      </div>
                    </div>
                  )}
                </DialogContent>
              </Dialog>
            </CardHeader>
            <CardContent>
              {usersLoading ? (
                <Skeleton className="h-64" />
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Name</TableHead>
                      <TableHead>Email</TableHead>
                      <TableHead>Role</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead className="w-24">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {users.map((user) => (
                      <TableRow key={user.id} data-testid={`user-row-${user.id}`}>
                        <TableCell className="font-medium">{user.name}</TableCell>
                        <TableCell>{user.email}</TableCell>
                        <TableCell>
                          <Badge variant={getRoleBadgeVariant(user.role)}>{user.role}</Badge>
                        </TableCell>
                        <TableCell>
                          <Switch
                            checked={user.active}
                            onCheckedChange={(checked) => updateUserMutation.mutate({ id: user.id, data: { active: checked } })}
                            data-testid={`switch-user-active-${user.id}`}
                          />
                        </TableCell>
                        <TableCell>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => openEditUserDialog(user)}
                            data-testid={`button-edit-user-${user.id}`}
                          >
                            <Pencil className="h-4 w-4" />
                          </Button>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="pipeline">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle>Pipeline Stages</CardTitle>
                <CardDescription>Configure your sales pipeline stages</CardDescription>
              </div>
              <Dialog open={isStageDialogOpen || !!editingStage} onOpenChange={(open) => {
                if (!open) {
                  setIsStageDialogOpen(false);
                  setEditingStage(null);
                  setStageForm({ name: "", order: 0, isClosed: false, isWon: false, color: "#6B7280" });
                }
              }}>
                <DialogTrigger asChild>
                  <Button onClick={() => setIsStageDialogOpen(true)} data-testid="button-create-stage">
                    <Plus className="h-4 w-4 mr-2" />
                    Add Stage
                  </Button>
                </DialogTrigger>
                <DialogContent>
                  <DialogHeader>
                    <DialogTitle>{editingStage ? "Edit Stage" : "Create New Stage"}</DialogTitle>
                  </DialogHeader>
                  <div className="space-y-4">
                    <div className="space-y-2">
                      <Label>Name</Label>
                      <Input
                        value={stageForm.name}
                        onChange={(e) => setStageForm({ ...stageForm, name: e.target.value })}
                        placeholder="Stage name"
                        data-testid="input-stage-name"
                      />
                    </div>
                    <div className="space-y-2">
                      <Label>Order</Label>
                      <Input
                        type="number"
                        value={stageForm.order}
                        onChange={(e) => setStageForm({ ...stageForm, order: parseInt(e.target.value) || 0 })}
                        data-testid="input-stage-order"
                      />
                    </div>
                    <div className="flex items-center justify-between">
                      <Label>Is Closed Stage</Label>
                      <Switch
                        checked={stageForm.isClosed}
                        onCheckedChange={(checked) => setStageForm({ ...stageForm, isClosed: checked })}
                        data-testid="switch-stage-closed"
                      />
                    </div>
                    <div className="flex items-center justify-between">
                      <Label>Is Won Stage</Label>
                      <Switch
                        checked={stageForm.isWon}
                        onCheckedChange={(checked) => setStageForm({ ...stageForm, isWon: checked, isClosed: checked ? true : stageForm.isClosed })}
                        data-testid="switch-stage-won"
                      />
                    </div>
                    <Button
                      className="w-full"
                      onClick={handleStageSubmit}
                      disabled={!stageForm.name || createStageMutation.isPending || updateStageMutation.isPending}
                      data-testid="button-submit-stage"
                    >
                      {createStageMutation.isPending || updateStageMutation.isPending
                        ? "Saving..."
                        : editingStage
                        ? "Update Stage"
                        : "Create Stage"}
                    </Button>
                  </div>
                </DialogContent>
              </Dialog>
            </CardHeader>
            <CardContent>
              {stagesLoading ? (
                <Skeleton className="h-64" />
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="w-12"></TableHead>
                      <TableHead>Name</TableHead>
                      <TableHead>Order</TableHead>
                      <TableHead>Closed</TableHead>
                      <TableHead>Won</TableHead>
                      <TableHead className="w-24">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {stages.map((stage) => (
                      <TableRow key={stage.id} data-testid={`stage-row-${stage.id}`}>
                        <TableCell>
                          <GripVertical className="h-4 w-4 text-muted-foreground" />
                        </TableCell>
                        <TableCell className="font-medium">{stage.name}</TableCell>
                        <TableCell>{stage.order}</TableCell>
                        <TableCell>
                          {stage.isClosed && <Badge variant="secondary">Closed</Badge>}
                        </TableCell>
                        <TableCell>
                          {stage.isWon && <Badge variant="default">Won</Badge>}
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-1">
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => openEditStageDialog(stage)}
                              data-testid={`button-edit-stage-${stage.id}`}
                            >
                              <Pencil className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => deleteStageMutation.mutate(stage.id)}
                              data-testid={`button-delete-stage-${stage.id}`}
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                    {stages.length === 0 && (
                      <TableRow>
                        <TableCell colSpan={6} className="text-center text-muted-foreground py-8">
                          No stages configured. Add your first pipeline stage.
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="settings">
          <Card>
            <CardHeader>
              <CardTitle>System Settings</CardTitle>
              <CardDescription>Configure system-wide settings</CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              {settingsLoading ? (
                <Skeleton className="h-32" />
              ) : (
                <>
                  <div className="space-y-2">
                    <Label>Minimum Margin Percent</Label>
                    <Input
                      type="number"
                      value={settingsForm.MIN_MARGIN_PERCENT || ""}
                      onChange={(e) => setSettingsForm({ ...settingsForm, MIN_MARGIN_PERCENT: parseFloat(e.target.value) || 0 })}
                      placeholder="15"
                      data-testid="input-min-margin"
                    />
                    <p className="text-sm text-muted-foreground">
                      The minimum profit margin required for deals
                    </p>
                  </div>

                  <div className="space-y-2">
                    <Label>Default Pipeline Stage</Label>
                    <Select
                      value={settingsForm.DEFAULT_STAGE_ID || ""}
                      onValueChange={(v) => setSettingsForm({ ...settingsForm, DEFAULT_STAGE_ID: v })}
                    >
                      <SelectTrigger data-testid="select-default-stage">
                        <SelectValue placeholder="Select default stage" />
                      </SelectTrigger>
                      <SelectContent>
                        {stages.map((stage) => (
                          <SelectItem key={stage.id} value={stage.id}>
                            {stage.name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <Button
                    onClick={() => saveSettingsMutation.mutate(settingsForm)}
                    disabled={saveSettingsMutation.isPending}
                    data-testid="button-save-settings"
                  >
                    <Save className="h-4 w-4 mr-2" />
                    {saveSettingsMutation.isPending ? "Saving..." : "Save Settings"}
                  </Button>
                </>
              )}
            </CardContent>
          </Card>

          <Card className="border-amber-500/20 bg-amber-500/5">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Zap className="h-5 w-5" />
                Lead Aging Automation
              </CardTitle>
              <CardDescription>Automatically move stale leads to reactivation stages</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <p className="text-sm text-muted-foreground">
                This automation moves non-sold leads based on days since last disposition:
              </p>
              <ul className="text-sm text-muted-foreground space-y-1 ml-4 list-disc">
                <li>30-90 days → reactivation_30</li>
                <li>90-180 days → reactivation_90</li>
                <li>180-730 days → reactivation_180</li>
                <li>730+ days → aged_out</li>
              </ul>
              <Button
                onClick={() => runAgingAutomationMutation.mutate()}
                disabled={runAgingAutomationMutation.isPending}
                variant="default"
                data-testid="button-run-aging-automation"
              >
                {runAgingAutomationMutation.isPending ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Running...
                  </>
                ) : (
                  <>
                    <Zap className="h-4 w-4 mr-2" />
                    Run Lead Aging Automation Now
                  </>
                )}
              </Button>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

