  windows: Array<{ id: string; position: number }>;
  leanTos: Array<{
    id: string;
    type: 'enclosed' | 'open' | 'gable';
    wall: 'front' | 'back' | 'left' | 'right';
    width: number;
    length: number;
    pitch: number;
    height: number;
    walls: { front: boolean; back: boolean; left: boolean; right: boolean };
    isOpen: boolean;
    position: number;
    wraparound: boolean;
    wraparoundCorner?: 'left' | 'right' | 'both';
    parentId?: string;
  }>;
  onLeanTosChange: (leanTos: Array<{
    id: string;
    type: 'enclosed' | 'open' | 'gable';
    wall: 'front' | 'back' | 'left' | 'right';
    width: number;
    length: number;
    pitch: number;
    height: number;
    walls: { front: boolean; back: boolean; left: boolean; right: boolean };
    isOpen: boolean;
    position: number;
    wraparound: boolean;
    wraparoundCorner?: 'left' | 'right' | 'both';
    parentId?: string;
  }>) => void;
  editingLeanToId: string | null;
  onEditingLeanToIdChange: (id: string | null) => void;
}

