  length,
  height,
  wallColor,
  roofColor,
  trimColor,
  roofStyle,
  roofPitch,
  onWidthChange,
  onLengthChange,
  onHeightChange,
  onWallColorChange,
  onRoofColorChange,
  onTrimColorChange,
  onRoofStyleChange,
  onRoofPitchChange,
  onAddRollupDoor,
  onAddPersonnelDoor,
  onAddWindow,
  editMode,
  onToggleEditMode,
  wallEnclosure,
  onWallEnclosureChange,
  customWalls,
  onCustomWallsChange,
  doors,
  windows,
  leanTos,
  onLeanTosChange,
  editingLeanToId,
  onEditingLeanToIdChange
