  const createIBeamGeometry = (length: number, taper: 'symmetric' | 'left' | 'right' | 'vertical' | 'none' = 'symmetric', scale: number = 1.0) => {
    const flangeWidth = 1.0 * scale;  // Wider flanges for dramatic look
