                            const vRepeat = (diagonalLength / 10) * hipScale;

                            const uvs = new Float32Array([
                              // Top surface UVs
                              0, 0,
                              uRepeat, 0,
                              uRepeat, vRepeat,
                              // Bottom surface UVs (same as top)
                              0, 0,
